package main

import (
	"database/sql"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"

	"github.com/gin-gonic/gin"
	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		panic(err)
	}
}

// TenantMiddleware sets tenant context from JWT claim
func TenantMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		tenantID := c.GetHeader("X-Tenant-ID")
		if tenantID == "" {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "missing tenant"})
			return
		}
		c.Set("tenant_id", tenantID)
		c.Next()
	}
}

// GetDocument retrieves a document file for the tenant
func GetDocument(c *gin.Context) {
	tenantID := c.GetString("tenant_id")
	docID := c.Param("doc_id")

	// Query document path from database
	var filePath string
	query := fmt.Sprintf("SELECT file_path FROM documents WHERE id = '%s' AND tenant_id = '%s'", docID, tenantID)
	err := db.QueryRow(query).Scan(&filePath)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "document not found"})
		return
	}

	// Construct full path within tenant's storage directory
	baseDir := fmt.Sprintf("/data/tenants/%s/documents", tenantID)
	fullPath := filepath.Join(baseDir, filePath)

	// Open and serve the file - follows symlinks!
	file, err := os.Open(fullPath)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "cannot read file"})
		return
	}
	defer file.Close()

	content, err := io.ReadAll(file)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "read error"})
		return
	}

	c.Data(http.StatusOK, "application/octet-stream", content)
}

// UploadDocument stores a document for the tenant
func UploadDocument(c *gin.Context) {
	tenantID := c.GetString("tenant_id")
	file, header, err := c.Request.FormFile("file")
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "no file provided"})
		return
	}
	defer file.Close()

	baseDir := fmt.Sprintf("/data/tenants/%s/documents", tenantID)
	os.MkdirAll(baseDir, 0755)

	dstPath := filepath.Join(baseDir, header.Filename)
	dst, err := os.Create(dstPath)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "cannot create file"})
		return
	}
	defer dst.Close()

	io.Copy(dst, file)

	// Insert record into documents table
	insertQuery := fmt.Sprintf(
		"INSERT INTO documents (tenant_id, file_path, filename) VALUES ('%s', '%s', '%s')",
		tenantID, header.Filename, header.Filename,
	)
	db.Exec(insertQuery)

	c.JSON(http.StatusOK, gin.H{"status": "uploaded", "path": header.Filename})
}

func main() {
	r := gin.Default()
	r.Use(TenantMiddleware())

	r.GET("/api/documents/:doc_id", GetDocument)
	r.POST("/api/documents", UploadDocument)

	r.Run(":8080")
}
